#[derive(Clone,Copy,Debug,PartialEq,Eq)] enum BindingKind{Mutable,LetImmutable,Const}
mod before {use crate::BindingKind;#[path="/Users/robertdevore/2026/Kujolang/kujo-repos/kujo/.audit-evidence/shared-compact-capture-v1-2026-10-28/baseline-binding-map.rs"]pub mod map;}
mod after {use crate::BindingKind;#[path="/Users/robertdevore/2026/Kujolang/kujo-repos/kujo/src/interpreter/binding_map.rs"]pub mod map;}
static LIVE:AtomicU64=AtomicU64::new(0);static PEAK:AtomicU64=AtomicU64::new(0);
struct Counter;
fn add(n:usize){let live=LIVE.fetch_add(n as u64,Relaxed)+n as u64;PEAK.fetch_max(live,Relaxed);}
unsafe impl GlobalAlloc for Counter{
 unsafe fn alloc(&self,l:Layout)->*mut u8{let p=unsafe{System.alloc(l)};if !p.is_null(){add(l.size());}p}
 unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{let q=unsafe{System.realloc(p,l,n)};if !q.is_null(){LIVE.fetch_sub(l.size() as u64,Relaxed);add(n);}q}
 unsafe fn dealloc(&self,p:*mut u8,l:Layout){LIVE.fetch_sub(l.size() as u64,Relaxed);unsafe{System.dealloc(p,l)}}
}
#[global_allocator]static ALLOC:Counter=Counter;
fn start()->u64{let base=LIVE.load(Relaxed);PEAK.store(base,Relaxed);base}
fn finish(base:u64)->(u64,u64){(LIVE.load(Relaxed)-base,PEAK.load(Relaxed)-base)}
fn main(){
 std::hint::black_box(ahash::RandomState::new());
 assert_eq!(std::mem::size_of::<before::map::BindingMap>(),std::mem::size_of::<after::map::BindingMap>());
 for width in [8192usize,16384]{for count in [1,8,32]{for calls in [1,16]{
  let names:HashMap<String,BindingKind>=(0..width).map(|i|(format!("extra_{i}"),BindingKind::Mutable)).collect();
  let mut old:Vec<_>=(0..count).map(|_|before::map::BindingMap::new()).collect();
  let mark=start();for _ in 0..calls{for owner in &mut old{let view=before::map::BindingMap::compact_from(names.keys().map(|k|(k.as_str(),owner.get(k).copied().unwrap_or(BindingKind::Mutable)))).unwrap();std::hint::black_box(view);}}let b=finish(mark);drop(old);
  let before_owners=LIVE.load(Relaxed);let mut new:Vec<_>=(0..count).map(|_|after::map::BindingMap::new()).collect();
  let mark=start();for _ in 0..calls{for owner in &mut new{if !owner.is_compact(){*owner=after::map::BindingMap::compact_from(names.keys().map(|k|(k.as_str(),owner.get(k).copied().unwrap_or(BindingKind::Mutable)))).unwrap();}std::hint::black_box(owner.clone());}}let a=finish(mark);drop(new);assert_eq!(LIVE.load(Relaxed),before_owners,"metadata outlived all owners/views");
