require 'json';require 'digest'
d=File.expand_path(__dir__);base=File.expand_path('../nested-path-storage-v1-2026-10-28',d)
read=->(p){JSON.parse(File.read(d+'/'+p))};sha=->(p){Digest::SHA256.file(p).hexdigest}
identity=read.call('allocation-build-identity.json');build=read.call('build-state.json')
raise 'Build identity' unless build['status']=='built'&&build['binary_sha256']==sha.call(d+'/candidate-kujo')&&build['library_sha256']==sha.call(d+'/candidate-library/libkujo-0204a58eed7d01d2.rlib')
raise 'Probe identity' unless identity['binary_sha256']==sha.call(d+'/task-allocation-probe')&&identity['library_sha256']==build['library_sha256']&&identity['source_sha256']==sha.call(d+'/task-allocation-probe.rs')&&identity['flags_sha256']==sha.call(d+'/current-link-flags.json')
r=read.call('local-target/report.json');raise 'Target incomplete' unless r['status']=='passed'
raise 'Target artifacts' unless r['binary_sha256']==build['binary_sha256']&&r['probe_sha256']==identity['binary_sha256']&&r['baseline_probe_sha256']==sha.call(base+'/task-allocation-probe')
raise 'Target runner' unless r['runner_sha256']==sha.call('benchmarks/langarena/probes/local-capture-allocations.rb')
key=->(row){row.values_at('bindings','operation','calls','mode')}
expected=[0,128,2048,8192].product(%w[read write],[1,16,32],%w[vm jit])
%w[rows baseline_rows].each{|group|raise 'Target coverage '+group unless r[group].map{|x|key.call(x)}.sort==expected.sort}
raise 'Target semantics' unless r['semantics'].map{|x|key.call(x)}.sort==[0,128,2048,8192].product(%w[read write],[1,16,32],%w[vm interpreter jit]).sort&&r['semantics'].all?{|x|x['exit']==0}
source_ids={};r['fixtures'].each{|f|{'source'=>'source_sha256','module_source'=>'module_sha256'}.each{|k,h|raise 'Target source hash' unless Digest::SHA256.hexdigest(f[k])==f[h];source_ids[f[h]]=true}}
(r['rows']+r['baseline_rows']+r['semantics']).each{|x|raise 'Target missing source' unless %w[source_sha256 module_sha256].all?{|k|source_ids[x[k]]}}
r['rows'].each do |c|
 b=r['baseline_rows'].find{|x|key.call(x)==key.call(c)}
 raise 'Target paired fixture mismatch' unless c.values_at('source_sha256','module_sha256')==b.values_at('source_sha256','module_sha256')
 raise 'Target total regression' unless %w[requests bytes].all?{|m|c[m]<=b[m]}
end
slopes=[]
[0,128,2048,8192].product(%w[read write],%w[vm jit]).each do |width,operation,mode|
 row={bindings:width,operation:operation,mode:mode}
 {'baseline'=>'baseline_rows','candidate'=>'rows'}.each do |label,group|
  a,b=r[group].select{|x|x.values_at('bindings','operation','mode')==[width,operation,mode]&&[16,32].include?(x['calls'])}.sort_by{|x|x['calls']}
  row[label]=%w[requests bytes].to_h{|m|[m,(b[m]-a[m])/16.0]}
 end
 raise 'Target per-call regression' unless %w[requests bytes].all?{|m|row['candidate'][m]<=row['baseline'][m]}
 raise 'Oversized improvement absent' if width==8192&&!%w[requests bytes].all?{|m|row['candidate'][m]<row['baseline'][m]}
 slopes<<row
end
cold=read.call('cold-control/report.json');raise 'Cold incomplete' unless cold['status']=='passed'
reference=JSON.parse(File.read(base+'/cold/report.json'))
%w[rows semantics].each do |group|
 normalize=->(rows){rows.map{|x|x.reject{|k,_|%w[requests bytes].include?(k)}}.sort_by{|x|JSON.generate(x.sort.to_h)}}
 raise 'Cold coverage/source drift' unless normalize.call(cold[group])==normalize.call(reference[group])
end
cold_pairs=cold['rows'].group_by{|x|x.values_at('bindings','depth','operation','calls','mode')}
raise 'Cold pair count' unless cold_pairs.size==36&&cold['rows'].size==72
cold_pairs.each do |key,rows|
 raise 'Cold build coverage' unless rows.map{|x|x['build']}.sort==%w[baseline candidate]
 b=rows.find{|x|x['build']=='baseline'};c=rows.find{|x|x['build']=='candidate'}
 raise 'Cold total regression' unless %w[requests bytes].all?{|m|c[m]<=b[m]}
end
split=read.call('split-control/report.json');raise 'Split incomplete' unless split['status']=='compared_without_regressions'
raise 'Split pairs' unless split['rows'].map{|x|x.values_at('bindings','operation','depth','calls','mode')}.sort==[0,128,2048,8192].product(%w[read write],[0,1,4],[1,16,32],%w[vm jit]).sort
raise 'Split semantics' unless split['semantics'].size==216&&split['semantics'].all?{|x|x['exit']==0}
(split['rows']+split['deltas']).each{|x|raise 'Split regression' unless %w[requests bytes].all?{|m|x['candidate'][m]<=x['baseline'][m]}}
dense=read.call('dense-controls/report.json');raise 'Dense incomplete' unless dense['status']=='passed'
raise 'Dense coverage' unless dense['rows'].map{|x|x.values_at('bindings','calls','mode')}.sort==[128,8192,16384].product([1,4],%w[vm jit]).sort&&dense['semantics'].size==18&&dense['semantics'].all?{|x|x['exit']==0}
(dense['rows']+dense['deltas']).each{|x|raise 'Dense regression' unless %w[requests bytes].all?{|m|x['candidate'][m]<=x['baseline'][m]}}
[[cold,'capture-cold-allocations.rb'],[split,'split-local-allocations.rb']].each do |report,runner|
 raise 'Control artifact identity' unless report['binary_sha256']==build['binary_sha256']&&report['probe_sha256']==identity['binary_sha256']&&report['baseline_probe_sha256']==sha.call(base+'/task-allocation-probe')
 raise 'Control runner identity' unless report['runner_sha256']==sha.call('benchmarks/langarena/probes/'+runner)
end
raise 'Dense artifact identity' unless dense['binary_sha256']==build['binary_sha256']&&dense['identities']=={base=>sha.call(base+'/task-allocation-probe'),d=>identity['binary_sha256']}&&dense['runner_sha256']==sha.call(d+'/dense-controls.rb')
raise 'Split semantic matrix' unless split['semantics'].map{|x|x.values_at('bindings','operation','depth','calls','mode')}.sort==[0,128,2048,8192].product(%w[read write],[0,1,4],[1,16,32],%w[vm interpreter jit]).sort
raise 'Dense semantic matrix' unless dense['semantics'].map{|x|x.values_at('bindings','calls','mode')}.sort==[128,8192,16384].product([1,4],%w[vm interpreter jit]).sort
File.write(d+'/target-verification.json',JSON.pretty_generate({status:'passed',slopes:slopes,local_pairs:48,local_semantics:72,cold_pairs:36,cold_observations:72,cold_semantics:54,split_pairs:144,split_semantics:216,dense_pairs:12,dense_semantics:18,verifier_sha256:sha.call(__FILE__),limitations:'Memory review and broad correctness/identity assembly remain separate gates'})+"\n")
puts 'Independent target and control allocation verification passed'
